// Determine if message is voice note or text
const msg = $input.first().json.message || {};
const chatId = msg.chat?.id;
const userId = msg.from?.id;
const username = msg.from?.username || msg.from?.first_name || 'Unknown Mortal';
const isVoice = !!(msg.voice);
const isText = !!(msg.text);
const fileId = msg.voice?.file_id || null;

if (!isVoice && !isText) {
  throw new Error('COSMIC_REJECTION: Oracle accepts voice notes and text only. No stickers. No GIFs.');
}

return [{
  json: {
    chatId,
    userId,
    username,
    isVoice,
    isText,
    fileId,
    rawText: msg.text || null,
    messageId: msg.message_id,
    receivedAt: new Date().toISOString()
  }
}];

// Merge transcribed text or raw text into a single question field
const classifier = $('📨 Message Type Classifier').first().json;
let question = '';

if (classifier.isVoice) {
  const whisper = $('👂 Whisper: Transcribe the Mortal\'s Words').first().json;
  question = whisper.data?.text || whisper.text || '';
} else {
  question = classifier.rawText || '';
}

question = question.trim();

if (!question || question.length < 3) {
  throw new Error('COSMIC_REJECTION: The Oracle could not decipher your words. Try again, mortal.');
}
if (question.length > 500) {
  question = question.substring(0, 500);
}

const sessionId = `oracle_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

return [{
  json: {
    question,
    sessionId,
    chatId: classifier.chatId,
    userId: classifier.userId,
    username: classifier.username,
    inputType: classifier.isVoice ? 'voice_note' : 'text_message',
    initiatedAt: new Date().toISOString(),
    questionLength: question.length,
    questionWordCount: question.split(/\s+/).length
  }
}];

const spiritualData = $('🔯 Invoke: Spiritual Weight Analyser').first().json;
const entropyData = $('⚛️ Invoke: Chaos Engine (Entropy Gatherer)').first().json;
const validatorData = $('⚖️ Reality Validation Matrix').first().json;

const stockFraction = entropyData.stockFraction || 0;
const windSpeed = entropyData.windSpeed || 0;
const apodTextLength = entropyData.apodTextLength || 0;
const redditSentiment = entropyData.redditSentiment || 0;
const quantumInt = entropyData.quantumInt || 0;
const wikiPageId = entropyData.wikiPageId || 0;
const moonIllumination = entropyData.moonIllumination || 0;

const normStock = (stockFraction / 9999) * 100;
const normWind = Math.min(windSpeed, 100);
const normApod = Math.min(apodTextLength / 20, 100);
const normReddit = ((redditSentiment + 1) / 2) * 100;
const normQuantum = (quantumInt / 255) * 100;
const normWiki = (wikiPageId % 100);
const normMoon = moonIllumination;

const rawEntropy = (normStock*0.10) + (normWind*0.10) + (normApod*0.10) + (normReddit*0.20) + (normQuantum*0.30) + (normWiki*0.10) + (normMoon*0.10);
const spiritualWeight = spiritualData.spiritualWeight || 0.5;
const spiritualModifier = (spiritualWeight - 0.5) * 0.30;
const finalEntropy = rawEntropy * (1 + spiritualModifier);
const decisionIndex = Math.floor(finalEntropy % 20);

return [{
  json: {
    question: spiritualData.question || validatorData.question,
    sessionId: spiritualData.sessionId || validatorData.sessionId,
    chatId: validatorData.chatId,
    userId: validatorData.userId,
    username: validatorData.username,
    inputType: validatorData.inputType,
    initiatedAt: validatorData.initiatedAt,
    entropyComponents: {
      financial: { raw: stockFraction, normalised: normStock, weight: 0.10 },
      meteorological: { raw: windSpeed, normalised: normWind, weight: 0.10 },
      cosmic: { raw: apodTextLength, normalised: normApod, weight: 0.10 },
      social: { raw: redditSentiment, normalised: normReddit, weight: 0.20 },
      quantum: { raw: quantumInt, normalised: normQuantum, weight: 0.30 },
      ancient: { raw: wikiPageId, normalised: normWiki, weight: 0.10 },
      celestial: { raw: moonIllumination, normalised: normMoon, weight: 0.10 }
    },
    spiritualWeight,
    spiritualTone: spiritualData.spiritualTone || 'neutral',
    rawEntropy,
    finalEntropy,
    decisionIndex,
    apodTitle: entropyData.apodTitle || 'Unknown Cosmic Object',
    wikiTitle: entropyData.wikiTitle || 'Unknown Ancient Text',
    moonPhase: entropyData.moonPhase || 'Unknown Phase',
    stockSymbol: entropyData.stockSymbol || 'UNKNOWN',
    redditTopPost: entropyData.redditTopPost || 'The void speaks',
    calculatedAt: new Date().toISOString()
  }
}];

const data = $input.first().json;
return [
  { json: { ...data, outputTarget: 'telegram_tts' } },
  { json: { ...data, outputTarget: 'slack' } },
  { json: { ...data, outputTarget: 'certificate' } },
  { json: { ...data, outputTarget: 'sheets' } },
  { json: { ...data, outputTarget: 'transparency' } },
  { json: { ...data, outputTarget: 'compliance' } },
  { json: { ...data, outputTarget: 'tapo' } }
];

const d = $input.first().json;
const now = new Date(d.calculatedAt || new Date());
const dateStr = now.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
const category = d.verdictCategory || 'neutral';
const accentColor = category === 'affirmative' ? '#00ffaa' : category === 'negative' ? '#ff4466' : '#d4af37';
const glowColor = category === 'affirmative' ? '#00ffaa44' : category === 'negative' ? '#ff446644' : '#d4af3744';

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;700&family=Cinzel+Decorative:wght@400;700&family=EB+Garamond:ital,wght@0,400;1,400&display=swap');
  *{margin:0;padding:0;box-sizing:border-box}
  html,body{min-height:100%;background:#030310;font-family:'EB Garamond',serif;overflow-x:hidden}
  body{padding:20px}
  .stars{position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:0}
  .star{position:absolute;width:2px;height:2px;background:white;border-radius:50%;animation:twinkle var(--d) infinite alternate}
  @keyframes twinkle{0%{opacity:0.1}100%{opacity:1}}
  .wrap{position:relative;z-index:1;width:100%;max-width:860px;margin:0 auto}
  .certificate{
    background:linear-gradient(135deg,#07071f 0%,#0d0d2e 40%,#07071f 100%);
    border:1px solid ${accentColor}33;
    position:relative;
    overflow:hidden;
    box-shadow:0 0 80px ${glowColor},inset 0 0 80px #+1234567890;
  }
  .certificate::before{
    content:'';
    position:absolute;top:0;left:0;right:0;bottom:0;
    background:radial-gradient(ellipse at 50% 0%,${glowColor} 0%,transparent 60%);
    pointer-events:none;
  }
  .corner{position:absolute;width:60px;height:60px;border-color:${accentColor};border-style:solid;opacity:0.6}
  .corner.tl{top:16px;left:16px;border-width:2px 0 0 2px}
  .corner.tr{top:16px;right:16px;border-width:2px 2px 0 0}
  .corner.bl{bottom:16px;left:16px;border-width:0 0 2px 2px}
  .corner.br{bottom:16px;right:16px;border-width:0 2px 2px 0}
  .inner{padding:40px 30px}
  .sigil{font-size:40px;letter-spacing:12px;color:${accentColor};opacity:0.4;margin-bottom:8px}
  .org{font-family:'Cinzel',serif;font-size:10px;letter-spacing:5px;color:${accentColor}99;text-transform:uppercase;margin-bottom:4px}
  .title{font-family:'Cinzel Decorative',serif;font-size:22px;color:${accentColor};text-shadow:0 0 30px ${accentColor};margin:12px 0 6px;line-height:1.3}
  .subtitle{font-family:'Cinzel',serif;font-size:10px;letter-spacing:3px;color:#ffffff44;margin-bottom:32px}
  .divider{width:100%;height:1px;background:linear-gradient(90deg,transparent,${accentColor}66,transparent);margin:20px 0}
  .issued{font-size:12px;color:#ffffff55;letter-spacing:2px;margin-bottom:20px}
  .question-label{font-family:'Cinzel',serif;font-size:10px;letter-spacing:4px;color:${accentColor}88;text-transform:uppercase;margin-bottom:10px}
  .question{font-size:18px;font-style:italic;color:#e8e0d0;line-height:1.6;margin-bottom:28px;padding:0 10px}
  .verdict-box{
    border:1px solid ${accentColor}55;
    padding:24px 20px;
    margin:0 0 28px;
    background:${glowColor};
    position:relative;
  }
  .verdict-label{font-family:'Cinzel',serif;font-size:10px;letter-spacing:5px;color:${accentColor}88;text-transform:uppercase;margin-bottom:12px}
  .verdict-text{
    font-family:'Cinzel',serif;
    font-size:18px;
    color:${accentColor};
    text-shadow:0 0 20px ${accentColor},0 0 60px ${accentColor}66;
    line-height:1.5;
  }
  .entropy-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-bottom:28px;text-align:left}
  .entropy-item{padding:10px;border:1px solid #ffffff11;background:#ffffff04}
  .entropy-key{font-family:'Cinzel',serif;font-size:9px;letter-spacing:3px;color:${accentColor}66;text-transform:uppercase;margin-bottom:4px}
  .entropy-val{font-size:13px;color:#ffffff88}
  .seal-line{font-family:'Cinzel',serif;font-size:10px;letter-spacing:2px;color:#ffffff33;margin:4px 0;line-height:1.6}
  .session{font-size:10px;color:#ffffff22;letter-spacing:1px;margin-top:12px;word-break:break-all}
</style>
</head>
<body>
<div class="stars" id="stars"></div>
<div class="wrap">
<div class="certificate">
  <div class="corner tl"></div>
  <div class="corner tr"></div>
  <div class="corner bl"></div>
  <div class="corner br"></div>
  <div class="inner">
    <div style="text-align:center">
      <div class="sigil">✦ ✧ ✦</div>
      <div class="org">The Quantum-Entangled Decision Oracle</div>
      <div class="title">Certificate of Cosmic Decision</div>
      <div class="subtitle">Issued by the Interdimensional Authority of Entropy</div>
    </div>
    <div class="divider"></div>
    <div style="text-align:center">
      <div class="issued">&#9654; ${dateStr} &nbsp;&#9670;&nbsp; Session ${d.sessionId || 'unknown'} &#9664;</div>
      <div class="question-label">The Question Posed to the Cosmos</div>
      <div class="question">&ldquo;${d.question || 'Unknown query'}&rdquo;</div>
      <div class="verdict-box">
        <div class="verdict-label">The Oracle Decrees</div>
        <div class="verdict-text">${d.oracleProphecy || 'The cosmos declines to elaborate.'}</div>
      </div>
    </div>
    <div class="entropy-grid">
      <div class="entropy-item"><div class="entropy-key">Quantum Seed</div><div class="entropy-val">${d.entropyComponents?.quantum?.raw ?? '?'}/255</div></div>
      <div class="entropy-item"><div class="entropy-key">Moon Phase</div><div class="entropy-val">${d.moonPhase || '?'} (${d.entropyComponents?.celestial?.raw ?? '?'}%)</div></div>
      <div class="entropy-item"><div class="entropy-key">Cosmic Signal</div><div class="entropy-val">${d.apodTitle ? d.apodTitle.substring(0,28)+'…' : '?'}</div></div>
      <div class="entropy-item"><div class="entropy-key">Social Pulse</div><div class="entropy-val">${d.entropyComponents?.social?.raw ?? '?'} sentiment</div></div>
      <div class="entropy-item"><div class="entropy-key">Entropy Index</div><div class="entropy-val">${d.decisionIndex ?? '?'}/19</div></div>
      <div class="entropy-item"><div class="entropy-key">Spiritual Weight</div><div class="entropy-val">${d.spiritualWeight ? (d.spiritualWeight*100).toFixed(0)+'%' : '?'} (${d.spiritualTone || '?'})</div></div>
    </div>
    <div class="divider"></div>
    <div style="text-align:center">
      <div class="seal-line">This decision was rendered by a quantum-entangled entropy engine</div>
      <div class="seal-line">and validated by Jev (TypeSafe AI System One)</div>
      <div class="seal-line">in accordance with EU AI Act Articles 12, 13, 19 &amp; 50 — Limited Risk Classification</div>
      <div class="session">Session: ${d.sessionId || ''}</div>
    </div>
  </div>
</div>
</div>
<script>
const s=document.getElementById('stars');
for(let i=0;i<80;i++){const el=document.createElement('div');el.className='star';el.style.cssText='left:'+Math.random()*100+'%;top:'+Math.random()*100+'%;--d:'+(2+Math.random()*4)+'s;opacity:'+Math.random();s.appendChild(el);}
</script>
</body></html>`;

return [{ json: { ...d, certificateHtml: html } }];

const html = $input.first().json.certificateHtml;
const buffer = Buffer.from(html, 'utf8');
return [{
  json: {},
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/html',
      fileName: 'oracle-certificate.html'
    }
  }
}];
